  function openTokenEditor(token){openModal('Nomear token',`<form id="token-name-form">${field('NOME','name',token.name)}<div class="field"><label>TIPO</label><select name="kind"><option value="hero" ${token.kind==='hero'?'selected':''}>Aliado</option><option value="enemy" ${token.kind==='enemy'?'selected':''}>Adversário</option><option value="neutral" ${token.kind==='neutral'?'selected':''}>Neutro</option></select></div></form>`,`<button class="secondary-btn" data-close-modal>Fechar</button><button class="primary-btn" data-save-token-name="${token.id}">Salvar</button>`);}

  function showMapPicker(){const c=currentCampaign();if(!c)return;const t=tabletopFor(c);openModal('Escolher mapa',`<div class="field"><label>IMAGEM DA BIBLIOTECA</label><select id="map-asset-select"><option value="">Mapa sem imagem</option>${state.assets.filter(a=>a.type?.startsWith('image/')).map(a=>`<option value="${a.id}" ${a.id===t.mapAssetId?'selected':''}>${escapeHtml(a.name)}</option>`).join('')}</select></div><p class="muted">Importe imagens pela Biblioteca para usá-las como mapa.</p>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-save-map>Aplicar mapa</button>`);}
  function chooseUpload(category='Outros'){const input=document.createElement('input');input.type='file';input.accept='image/*,.pdf,.txt';input.multiple=true;input.onchange=async()=>{for(const file of [...input.files]){if(file.size>1500000){toast(`${file.name}: limite local de 1,5 MB por arquivo.`);continue;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});state.assets.push({id:uid(),name:file.name,type:file.type||'application/octet-stream',size:file.size,category,data});}catch{toast(`Não foi possível ler ${file.name}.`);}}save();render();if(state.assets.length)logActivity('Novos arquivos foram adicionados à biblioteca.');};input.click();}
  function safeImport(data){if(!data||typeof data!=='object'||!Array.isArray(data.campaigns)||!Array.isArray(data.characters)||!Array.isArray(data.systems))throw new Error('Arquivo de backup inválido.');const base=defaults();state={...base,...data,assets:Array.isArray(data.assets)?data.assets:[],rolls:Array.isArray(data.rolls)?data.rolls:[],activity:Array.isArray(data.activity)?data.activity:[],settings:{...base.settings,...(data.settings||{})}};state.campaigns.forEach(c=>{c.sessions=c.sessions||[];c.tabletop=c.tabletop||{grid:state.settings.grid,gridType:state.settings.gridType,tokens:[],initiative:[],round:1,mapAssetId:null,zoom:1,panX:0,panY:0};c.chat=c.chat||[];});save();render();toast('Cópia restaurada com sucesso.');}
  function handleAction(action){const c=currentCampaign(),t=c&&tabletopFor(c);switch(action){case'create-campaign':createCampaign();break;case'create-character':createCharacter();break;case'create-system':createSystem();break;case'new-session':if(c)createSession(c);else toast('Crie uma campanha primeiro.');break;case'add-token':createToken();break;case'add-character-token':if(!c)return;{const ch=state.characters[0];if(!ch){toast('Crie um personagem antes de vinculá-lo.');return;}const token={id:uid(),name:ch.name,kind:'hero',x:160+(t.tokens.length%4)*64,y:140+Math.floor(t.tokens.length/4)*64,characterId:ch.id};t.tokens.push(token);save();renderTabletop();}break;case'toggle-grid':if(t){t.gridType=t.gridType==='none'?'square':t.gridType==='square'?'hex':'none';save();renderTabletop();}break;case'map-image':showMapPicker();break;case'center-map':if(t){t.panX=0;t.panY=0;t.zoom=1;save();renderTabletop();}break;case'save-notes':if(c){t.notes=$('#table-notes')?.value||'';save();toast('Notas salvas neste dispositivo.');}break;case'start-combat':if(!t||!t.tokens.length){toast('Adicione ao menos um token antes de iniciar o combate.');return;}t.initiative=t.tokens.map(x=>({...x,score:Number(x.initiative)||1+Math.floor(Math.random()*20)})).sort((a,b)=>b.score-a.score);t.turnIndex=0;t.round=1;save();renderTabletopPanel();break;case'next-turn':if(t?.initiative.length){t.turnIndex=(t.turnIndex+1)%t.initiative.length;if(t.turnIndex===0)t.round=(t.round||1)+1;save();renderTabletopPanel();}break;case'end-combat':if(t){t.initiative=[];t.turnIndex=0;t.round=1;save();renderTabletopPanel();}break;case'upload-asset':openModal('Importar para biblioteca',`<div class="field"><label>CATEGORIA</label><select id="upload-category"><option>Mapas</option><option>Tokens</option><option>Retratos</option><option selected>Outros</option></select></div><p class="muted">Arquivos de até 1,5 MB são guardados localmente. Imagens podem ser usadas como mapa.</p>`,`<button class="secondary-btn" data-close-modal>Cancelar</button><button class="primary-btn" data-start-upload>Escolher arquivo</button>`);break;case'export-data':download('seed-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));break;case'import-data':{const input=document.createElement('input');input.type='file';input.accept='application/json';input.onchange=()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{safeImport(JSON.parse(reader.result));}catch(e){toast(e.message||'Não foi possível restaurar o arquivo.');}};reader.readAsText(file);};input.click();}break;case'clear-data':if(confirm('Apagar todas as campanhas, personagens, rolagens e arquivos locais? Esta ação não pode ser desfeita.')){state=defaults();save();navigate('dashboard');toast('Dados locais apagados.');}break;}}

  async function openMemberManager(campaignId){const campaign=campaignById(campaignId);if(!campaign)return;try{const members=await window.SEED_CLOUD.listMembers(campaignId);const rows=members.length?members.map(member=>`<div class="cloud-member-row"><div><b>${member.status==='pending'?'Solicitação pendente':'Participante'}</b><small>${escapeHtml(member.user_id)}</small></div><div class="cloud-member-actions">${member.status==='pending'?`<button class="secondary-btn" data-approve-member="${escapeHtml(member.user_id)}" data-campaign-id="${escapeHtml(campaignId)}">Aprovar</button>`:''}<button class="danger-btn" data-remove-member="${escapeHtml(member.user_id)}" data-campaign-id="${escapeHtml(campaignId)}">${member.status==='pending'?'Recusar':'Remover'}</button></div></div>`).join(''):'<p class="muted">Ainda não há solicitações nem participantes.</p>';openModal(`Participantes · ${escapeHtml(campaign.name)}`,`<div class="cloud-members-list">${rows}</div><div class="cloud-invite-box"><p>Crie um código temporário para convidar um jogador. O código é mostrado uma única vez.</p><button class="secondary-btn" data-create-invite="${escapeHtml(campaignId)}">＋ Gerar convite</button><div id="cloud-invite-result"></div></div>`,'<button class="secondary-btn" data-close-modal>Fechar</button>',true);}catch(error){toast(`Não foi possível carregar participantes: ${error.message||error}`);}}
  document.addEventListener('click',async e=>{const button=e.target.closest('[data-members],[data-create-invite],[data-approve-member],[data-remove-member]');if(!button)return;const cloud=window.SEED_CLOUD;if(button.dataset.members){await openMemberManager(button.dataset.members);return;}if(button.dataset.createInvite){button.disabled=true;try{const {data,error}=await cloud.createInvite(button.dataset.createInvite);if(error)throw error;const result=$('#cloud-invite-result');if(result)result.innerHTML=`<label class="field">CÓDIGO DE CONVITE<input readonly value="${escapeHtml(data)}" id="cloud-invite-code"></label><button class="secondary-btn" data-copy-invite>Copiar código</button>`;}catch(error){toast(`Não foi possível gerar convite: ${error.message||error}`);}finally{button.disabled=false;}return;}if(button.hasAttribute('data-copy-invite')){const input=$('#cloud-invite-code');try{await navigator.clipboard.writeText(input.value);toast('Código copiado.');}catch{input.select();document.execCommand('copy');toast('Código copiado.');}return;}const campaignId=button.dataset.campaignId,userId=button.dataset.approveMember||button.dataset.removeMember;try{if(button.dataset.approveMember){const {error}=await cloud.approveMember(campaignId,userId);if(error)throw error;toast('Participante aprovado.');}else{if(!confirm('Remover esta pessoa da campanha?'))return;const {error}=await cloud.removeMember(campaignId,userId);if(error)throw error;toast('Participante removido.');}await cloud.refresh();await openMemberManager(campaignId);}catch(error){toast(`Não foi possível atualizar participantes: ${error.message||error}`);}});
